// ZIGMon ESP32 Gateway - the web UI's static files, gzipped in flash (web_assets.h is
// generated by tools/esp32-embed-web.py from the readable sources in web/).
#include "api.h"

#include "web_assets.h"

namespace gw {
namespace api {

esp_err_t asset(httpd_req_t* req) {
  https::Response r;
  char route[64];
  routeOf(req->uri, route, sizeof route);
  if (req->method != HTTP_GET) {
    https::error(r, 405, "method not allowed");
    return https::send(req, r);
  }
  const char* want = (strcmp(route, "/") == 0) ? "/index.html" : route;
  for (size_t i = 0; i < WEB_ASSET_COUNT; i++) {
    const WebAsset& a = WEB_ASSETS[i];
    if (strcmp(a.path, want) != 0) continue;
    r.contentType = a.type;
    r.asset = a.data;
    r.assetLen = a.len;
    r.html = strcmp(a.path, "/index.html") == 0;
    // index.html names the others with ?v=<hash>, so they can be cached for good.
    r.cacheControl = r.html ? "no-cache" : "public, max-age=31536000, immutable";
    return https::send(req, r);
  }
  r.status = 404;
  r.contentType = "text/plain";
  r.body = "Not found";
  return https::send(req, r);
}

}  // namespace api
}  // namespace gw
